message.content:
{
  "title": "The Glass Diver's Rescue",
  "gate_token": "XyxgNFWuBgurmh04y-adwA",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The party stands before the ruined city gates.",
      "visual_description": "Crumbling stone gates flanked by tattered royal banners in faded purple and gold, the city beyond a maze of broken towers.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 2,
      "caption": "Mara consults her map at a crossroads.",
      "visual_description": "A dusty intersection with cracked cobblestones, Mara unrolls a weathered map while the tin fox sniffs the air.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 3,
      "caption": "The oracle lamp warns of a cursed tower ahead.",
      "visual_description": "A leaning stone tower with dark windows, the lamp's flame flickers as its eye glows.",
      "characters": ["oracle_lamp", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 4,
      "caption": "The glass diver scouts through a shattered window.",
      "visual_description": "A reflection pool inside a ruined hall, the diver's helmet catches fractured light as he steps through the glass.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 5,
      "caption": "They find the sleeping tax collector in a collapsed archive.",
      "visual_description": "A room with toppled shelves and scattered ledgers, the collector snores on a stack of papers, stamp still in hand.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "The tin fox discovers a hidden passage behind a tapestry.",
      "visual_description": "A faded tapestry showing a royal hunt, the fox's metal tail winds as it pushes aside the fabric to reveal a dark corridor.",
      "characters": ["tin_fox", "glass_diver"]
    },
    {
      "scene_number": 7,
      "caption": "Mara deciphers a riddle on a magic door.",
      "visual_description": "A stone door engraved with shifting symbols, Mara traces the lines with ink-stained fingers while the lamp casts moving shadows.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 8,
      "caption": "The glass diver swims through a mirror to open the door from inside.",
      "visual_description": "A tall mirror in a dusty chamber, the diver's hand emerges from its surface to turn a hidden lever.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 9,
      "caption": "Armored patrols march through the plaza above.",
      "visual_description": "From a sewer grate, the party sees boots and spear shafts passing on the cobblestones above, torchlight glinting off armor.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 10,
      "caption": "The sleeping tax collector wakes and refuses to move.",
      "visual_description": "He sits on a crate in a narrow alley, rubbing his eyes and clutching his ledger, stubbornly staying put.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 11,
      "caption": "The oracle lamp's flame reveals a secret stair.",
      "visual_description": "The lamp casts its light on a wall, showing a spiral staircase hidden behind a false panel of stone.",
      "characters": ["oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 12,
      "caption": "They ascend into an old throne room with a magic seal.",
      "visual_description": "Sunlight streams through broken stained glass, illuminating a seal on the floor that pulses with blue light.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 13,
      "caption": "The glass diver uses his helmet to reflect the seal's magic.",
      "visual_description": "He positions his helmet to catch the light, bending the beam onto a keyhole in a nearby door.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 14,
      "caption": "They rescue a captive from a cell beneath the tower.",
      "visual_description": "A damp stone cell with iron bars, the party helps a thin figure in rags step out, the lamp lighting the way.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 15,
      "caption": "Patrols close in as they flee through the market district.",
      "visual_description": "Collapsed stalls and scattered goods, armored figures block the far end of the street, horns sounding.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 16,
      "caption": "The tin fox triggers a diversion with a barrel of oil.",
      "visual_description": "The fox rolls a small barrel toward a brazier, then scampers away as flames erupt, creating smoke cover.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 17,
      "caption": "They race across the old bridge toward the outer gate.",
      "visual_description": "A stone bridge with missing balusters, the party runs under a sky lit by distant fires, the city behind them.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 18,
      "caption": "The glass diver smashes the bridge's final lock with his helmet.",
      "visual_description": "At the bridge's far end, a heavy chain gate; the diver strikes the lock with his helmet, cracking both, and they pass through to safety.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    }
  ]
}

